await users.insertOne({ email: "a@example.com", name: "Ada" })
await users.updateOne({ email: "a@example.com" }, { $set: { name: "Ada Lovelace" } })
const user = await users.findOne({ email: "a@example.com" })

// tốt: lọc trước, giảm dữ liệu đi vào các stage sau
db.orders.aggregate([
  { $match: { createdAt: { $gte: startOfMonth } } },
  { $unwind: '$items' },
  { $group: { _id: '$items.sku', total: { $sum: '$items.qty' } } }
])

// A. giữ mảng có trần: chỉ lưu 20 comment mới nhất để hiển thị nhanh
db.posts.updateOne(
  { _id: postId },
  { $push: { recentComments: { $each: [comment], $slice: -20 } } }
)
// B. tách comments ra collection riêng, tham chiếu postId + index theo postId

const stream = db.collection('orders').watch([
  { $match: { 'fullDocument.status': 'paid' } }
], { fullDocument: 'updateLookup' })

for await (const change of stream) {
  await sendInvoice(change.fullDocument)
}

// query: status bằng, sort theo createdAt, lọc amount theo khoảng
db.orders.find({ status: 'paid', amount: { $gte: 100000 } }).sort({ createdAt: -1 })

db.orders.createIndex({ status: 1, createdAt: -1, amount: 1 })  // E - S - R

db.users.createIndex({ status: 1, email: 1 })

// covered: lọc theo status, chỉ lấy email, tắt _id
db.users.find({ status: 'active' }, { _id: 0, email: 1 })

// không covered: lấy thêm name (không có trong index) → phải FETCH document
db.users.find({ status: 'active' }, { _id: 0, email: 1, name: 1 })

// sparse: chỉ index user có field phone
db.users.createIndex({ phone: 1 }, { sparse: true })

// partial: chỉ index đơn chưa hoàn tất — thứ mà dashboard truy vấn liên tục
db.orders.createIndex(
  { createdAt: -1 },
  { partialFilterExpression: { status: { $in: ['pending', 'processing'] } } }
)

db.createCollection('orders', {
  validator: {
    $jsonSchema: {
      bsonType: 'object',
      required: ['userId', 'total', 'status'],
      properties: {
        userId: { bsonType: 'objectId' },
        total: { bsonType: 'int', minimum: 0 },
        status: { enum: ['pending', 'paid', 'cancelled'] }
      }
    }
  },
  validationLevel: 'moderate',
  validationAction: 'error'
})
